#include <bits/stdc++.h>

using namespace std;

using int64 = long long;

constexpr int64 P = 1000000007;

struct FiniteField {
 private:
  int64 x;
 public:
  FiniteField(int64 x) : x(x) {
    if (x > P || x < 0) { cerr << "Invalid FiniteField!" << endl; exit(1); }
  }
  FiniteField() : x(0) {}
  int64 Value() const { return x; }
  inline FiniteField operator+(FiniteField o) const {
    FiniteField r(*this); r += o; return r;
  }
  inline FiniteField operator-(FiniteField o) const {
    FiniteField r(*this); r -= o; return r;
  }
  inline FiniteField operator* (FiniteField o) const {
    FiniteField r(*this); r *= o; return r;
  }
  inline FiniteField operator/ (FiniteField o) const {
    FiniteField r(*this); r /= o; return r;
  }
  inline void operator+= (FiniteField o) { x = (x + o.x) % P; }
  inline void operator-= (FiniteField o) { x = (x + P - o.x) % P; }
  inline void operator*= (FiniteField o) { x = (x * o.x) % P; }
  void operator/=(FiniteField o) {
    int64 p = P - 2; while (p) { if (p % 2) { *this *= o; } o *= o; p /= 2; }
  }
};

template<typename T>
vector<vector<T>> matrix_multiply(const vector<vector<T>>& a, const vector<vector<T>>& b) {
  int n = a.size();
  int m = a[0].size();
  if (b.size() != m) {
    cerr << "Dimension mismatch for multiplication!" << endl;
    exit(1);
  }
  int l = b[0].size();
  vector<vector<T>> result(n, vector<T>(l));
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < l; j++) {
      for (int k = 0; k < m; k++) {
        result[i][j] += a[i][k] * b[k][j];
      }
    }
  }
  return result;
}

template<typename T>
vector<T> matrix_vector_multiply(const vector<vector<T>>& matrix, const vector<T>& v) {
  int n = matrix.size();
  int m = matrix[0].size();
  if (v.size() != m) {
    cerr << "Dimension mismatch for matrix-vector multiplication!" << endl;
    exit(1);
  }
  vector<T> res(n);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      res[i] += matrix[i][j] * v[j];
    }
  }
  return res;
}

template<typename T>
vector<vector<T>> create2D(int d1, int d2, T val) {
  return vector<vector<T>>(d1, vector<T>(d2, val));
}

template<typename T>
vector<vector<vector<T>>> create3D(int d1, int d2, int d3, T val) {
  return vector<vector<vector<T>>>(
      d1, vector<vector<T>>(d2, vector<T>(d3, val)));
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int64 n;
  int d;
  cin >> n >> d;

  auto shifts = create3D<FiniteField>(d, d + 1, d + 1, 0);
  for (int k = 0; k < d; k++) {
    for (int i = 0; i < d; i++) {
      shifts[k][i][(i + k) % d] = 1;
    }
    shifts[k][d][d] = 1;
  }

  auto units = create3D<FiniteField>(d, d + 1, d + 1, 0);
  for (int k = 0; k < d; k++) {
    for (int i = 0; i <= d; i++) {
      units[k][i][i] = 1;
    }
    for (int i = 0; i <= d; i++) {
      units[k][k][i] = 1;
    }
  }

  auto identity = create2D<FiniteField>(d + 1, d + 1, 0);
  for (int i = 0; i <= d; i++) {
    identity[i][i] = 1;
  }

  map<int64, vector<vector<FiniteField>>> cache;

  function<vector<vector<FiniteField>>(int64)> find_matrix =
      [&](int64 p) -> vector<vector<FiniteField>> {
    if (cache.count(p)) {
      return cache[p];
    }

    if (p <= d) {
      auto matrix = identity;
      for (int k = 0; k < p; k++) {
        matrix = matrix_multiply(units[k], matrix);
      }
      cache[p] = matrix;
      return matrix;
    }

    int64 child_p = d;
    while ((p + child_p - 1) / child_p > d) {
      child_p *= d;
    }
    auto child = find_matrix(child_p);
    auto matrix = child;
    int64 remaining_p = p;
    remaining_p -= child_p;
    for (int k = 1; k < d; k++) {
      if (remaining_p >= child_p) {
        matrix = matrix_multiply(shifts[d - k], matrix);
        matrix = matrix_multiply(matrix, shifts[k]);
        matrix = matrix_multiply(matrix, child);
        remaining_p -= child_p;
      } else if (remaining_p > 0) {
        auto rem_matrix = find_matrix(remaining_p);
        matrix = matrix_multiply(shifts[d - k], matrix);
        matrix = matrix_multiply(matrix, rem_matrix);
        matrix = matrix_multiply(matrix, shifts[k]);
        remaining_p = 0;
      } else {
        break;
      }
    }
    cache[p] = matrix;
    return matrix;
  };

  auto matrix = find_matrix(n);
  vector<FiniteField> base_vector(d + 1, 0);
  base_vector[d] = 1;
  auto final_vector = matrix_vector_multiply(matrix, base_vector);
  FiniteField answer = 0;
  for (const auto& val : final_vector) answer += val;
  cout << answer.Value() << "\n";
}
